import { NavLink } from "react-router-dom";
import styled from "styled-components";
import { useContext } from "react";
import { ThemeContext } from "./contexts/ThemeContext"; // import context

const Nav = styled.nav`
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 80px; /* wider navbar */
  height: 70px;
  background: ${({ theme }) =>
    theme.darkMode
      ? "linear-gradient(90deg, #2c2c2c, #1e1e1e)"
      : "linear-gradient(90deg, #ffffff, #f0f0f0)"};
  border-bottom: 1px solid ${({ theme }) => (theme.darkMode ? "#333" : "#ccc")};
  position: sticky;
  top: 0;
  z-index: 100;
  transition: background 0.3s, border-color 0.3s;
`;

const LinksWrapper = styled.div`
  display: flex;
  gap: 40px;
  align-items: center;
`;

const StyledLink = styled(NavLink)`
  color: ${({ theme }) => (theme.darkMode ? "white" : "#121212")};
  text-decoration: none;
  font-size: 18px;
  font-weight: 500;
  padding: 10px 15px;
  border-radius: 5px;
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
  height: 100%;

  &:hover {
    background-color: #e50914;
    color: #fff;
    transform: translateY(-2px);
  }

  &.active {
    color: #e50914;
    font-weight: 600;
    background-color: transparent;
    border-bottom: 3px solid #e50914;
  }
`;

const DarkModeButton = styled.button`
  padding: 6px 12px;
  font-size: 14px;
  background-color: #e50914;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.25s ease;

  &:hover {
    background-color: #ff1a2d;
  }
`;

const Navbar = () => {
  const { darkMode, toggleDarkMode } = useContext(ThemeContext);

  return (
    <Nav theme={{ darkMode }}>
      <div style={{ fontSize: "1.5rem", fontWeight: "700", color: "#e50914" }}>
        MyBooks
      </div>
      <LinksWrapper>
        <StyledLink to="/" theme={{ darkMode }}>
          Home
        </StyledLink>
        <StyledLink to="/books" theme={{ darkMode }}>
          All Books
        </StyledLink>
        <StyledLink to="/add" theme={{ darkMode }}>
          Add Book
        </StyledLink>
        <StyledLink to="/mybooks" theme={{ darkMode }}>
          My Books
        </StyledLink>
        <StyledLink to="/about" theme={{ darkMode }}>
          About
        </StyledLink>
        <DarkModeButton onClick={toggleDarkMode}>
          {darkMode ? "☀️" : "🌙"}
        </DarkModeButton>
      </LinksWrapper>
    </Nav>
  );
};

export default Navbar;
